import {searchInventory,freshness} from './inventory-search.js';
import {$,esc,money,time,state,onData,createTool,showTool,options,integer,ranges,rangeFields,preview,compare,exportCSV,activateInitial} from './workbench.js';
import {filterItems} from './tools-core.js';
import {safeImageURL} from './media.js';
const search=createTool('search','自定搜索','找到你要的那组数值。','多孔数值、预算和收藏热度一起筛选，结果可直接比较或观察趋势。',`<section class="card"><div class="card-heading"><div><h2>自定搜索 <span class="tag">全量收录库存</span></h2><p>搜索累计收录的真实商品；历史观察价不代表当前在售，购买前请核验。</p></div><button class="button secondary" id="search-reset" type="button">清空条件</button></div><form id="search-form" class="tool-form"><div class="tool-grid"><label>数据范围<select id="search-scope"><option value="inventory">全部已收录库存</option><option value="sample">本轮行情样本</option></select></label><label>新鲜度<select id="search-fresh"><option value="all">全部观察记录</option><option value="recent">仅近65分钟观察</option></select></label><label>名称或商品编号<input id="search-query" placeholder="输入关键字"></label><label>品类<select id="search-category"><option value="">全部品类</option><option value="character">角色皮肤</option><option value="weapon">武器皮肤</option></select></label><label>谪星<select id="search-skin"></select></label><label>已解锁孔数<select id="search-holes"><option value="">不限孔数</option><option value="0">无星格</option><option value="1">1孔</option><option value="2">2孔</option><option value="3">3孔</option><option value="4">4孔</option></select></label><label>最低价 / 元<input id="search-price-min" type="number" min="0" step="0.01" placeholder="不限"></label><label>最高价 / 元<input id="search-price-max" type="number" min="0" step="0.01" placeholder="不限"></label><label>最低收藏数<input id="search-favorites" type="number" min="0" placeholder="不限"></label><label>商品范围<select id="search-state"><option value="all">全部观察样本</option><option value="no">不含公示期</option><option value="lottery">已确认且未截止的抽签</option></select></label></div><div class="tool-slot-grid" id="search-slots">${rangeFields('search')}</div><div class="tool-checks">${Array.from({length:4},(_,i)=>`<label><input type="checkbox" id="search-unlocked-${i}">第${i+1}格须已解锁</label>`).join('')}</div><div class="tool-actions"><button type="submit" class="button">应用搜索</button><input id="search-name" placeholder="给当前条件命名"><button type="button" class="button secondary" id="search-save">保存条件</button><button type="button" class="button secondary" id="search-trend">查看条件趋势</button></div></form><div id="search-presets" class="tool-chips"></div><p id="search-error" class="tool-message" role="status"></p></section><section class="card"><div class="card-heading"><div><h2 id="search-count">搜索结果</h2><p id="search-source"></p></div><div class="tool-actions"><select id="search-sort" aria-label="结果排序"><option value="price">价格升序</option><option value="favorites">收藏降序</option><option value="holes">孔数降序</option><option value="recent">最近观察</option></select><button type="button" class="button secondary" id="search-export">导出结果</button></div></div><div class="table-scroll"><table><thead><tr><th>商品</th><th>星格 / 解锁</th><th>挂牌价 / 收藏</th><th>操作</th></tr></thead><tbody id="search-results"></tbody></table></div><div class="tool-pagination"><button id="search-prev" class="button secondary">上一页</button><span id="search-page"></span><button id="search-next" class="button secondary">下一页</button></div></section>`,'⌕');
let result=[],page=1,saved=[];try{const parsed=JSON.parse(localStorage.getItem('zx-search-presets')||'[]');if(Array.isArray(parsed))saved=parsed.slice(0,20)}catch{}
const ids=['scope','fresh','query','category','skin','holes','price-min','price-max','favorites','state'];
function price(id){const value=$('#search-'+id).value.trim();if(!value)return null;if(!/^\d+(?:\.\d{1,2})?$/.test(value))throw Error('价格最多两位小数');const cents=Math.round(Number(value)*100);if(!Number.isSafeInteger(cents)||cents>1e12)throw Error('价格超出范围');return cents}
function filter(){const priceMin=price('price-min'),priceMax=price('price-max');if(priceMin!=null&&priceMax!=null&&priceMin>priceMax)throw Error('最低价不能高于最高价');return {query:$('#search-query').value.trim(),category:$('#search-category').value,skin:$('#search-skin').value,holes:$('#search-holes').value,priceMin,priceMax,favoritesMin:integer($('#search-favorites').value,'收藏数'),publicity:$('#search-state').value==='no'?'no':'all',lotteryOnly:$('#search-state').value==='lottery',ranges:ranges('search'),requireUnlocked:Array.from({length:4},(_,i)=>$('#search-unlocked-'+i).checked)}}
let archive=null,archivePromise=null,searchRevision=0,sourceLabel='',remoteCount=null;
async function loadArchive(){if(archive)return archive;if(!archivePromise)archivePromise=fetch('inventory/index.json',{cache:'no-cache'}).then(async response=>{if(!response.ok)throw Error('库存索引暂不可用，请重试');const data=await response.json();if(!Array.isArray(data.items))throw Error('库存索引格式异常');sourceLabel='发布时库存快照 · '+time(data.updatedAt);return archive=data.items}).catch(error=>{archivePromise=null;throw error});return archivePromise}
async function apply(reset=true){const revision=++searchRevision;if(reset)page=1;try{const criteria=filter();criteria.recentOnly=$('#search-fresh').value==='recent';const sort=$('#search-sort').value;$('#search-error').textContent='正在搜索…';let data;if($('#search-scope').value==='sample'){data=searchInventory(state.pool,{filter:criteria,sort});sourceLabel='本轮行情样本'}else{let response;try{response=await fetch('/api/inventory/search?'+new URLSearchParams({filter:JSON.stringify(criteria),sort,page:String(page)}),{cache:'no-store'})}catch{}if(response?.ok){data=await response.json();sourceLabel=data.source==='cloud'?'云端实时库存库':'本机实时库存库'}else if(response&&response.status!==404&&response.status!==405){throw Error('库存服务暂不可用，请稍后重试')}else{data=searchInventory(await loadArchive(),{filter:criteria,sort});sourceLabel='发布时库存快照'}}if(revision!==searchRevision)return;result=data.items;remoteCount=data.paginated?data.count:null;$('#search-export').textContent=remoteCount===null?'导出结果':'导出本页';$('#search-error').textContent='';drawResults()}catch(error){if(revision===searchRevision){result=[];remoteCount=null;drawResults();$('#search-error').textContent=error.message}}}
const mediaCache=new Map();async function fullItem(item){if(item.previewFrames?.length)return item;let response;try{response=await fetch('/api/inventory/item?id='+encodeURIComponent(item.id))}catch{}if(response?.ok)return (await response.json()).item;if(response&&response.status!==404)throw Error('预览资料暂不可用，请重试');if(!mediaCache.has(item.equipType))mediaCache.set(item.equipType,fetch('inventory/'+encodeURIComponent(item.equipType)+'.json').then(r=>{if(!r.ok)throw Error('预览资料暂不可用');return r.json()}).catch(e=>{mediaCache.delete(item.equipType);throw e}));const data=await mediaCache.get(item.equipType);const media=data.items.find(i=>i.id===item.id);return {...media,...item,previewFrames:media?.previewFrames??[]}}
async function verifyItem(item,button){button.disabled=true;try{const response=await fetch('/api/inventory/verify?id='+encodeURIComponent(item.id),{cache:'no-store'});let data;try{data=await response.json()}catch{throw Error('当前为静态快照，需连接后端才能即时核验')}if(!response.ok)throw Error(data.error||'核验暂不可用');const oldPrice=item.priceCents;Object.assign(item,data.item,{observedAt:data.observedAt});if(archive){const old=archive.find(i=>i.id===item.id);if(old)Object.assign(old,item)}$('#search-error').textContent=oldPrice!==item.priceCents?'价格已变动：'+money(oldPrice)+' → '+money(item.priceCents):'已核验当前详情 · '+time(data.observedAt);drawResults()}catch(error){$('#search-error').textContent=error.message}finally{button.disabled=false}}
function drawResults(){const pages=Math.max(1,Math.ceil((remoteCount??result.length)/20));page=Math.min(page,pages);$('#search-count').textContent=`${remoteCount??result.length} 件匹配商品`;$('#search-source').textContent=`${sourceLabel} · 收录范围内搜索，滚动采集不等于同时点全市场；旧记录请先核验。`;
 $('#search-results').innerHTML=(remoteCount===null?result.slice((page-1)*20,page*20):result).map((item,n)=>{const src=safeImageURL(item.thumbnail);return `<tr><td><div class="item-cell">${src?`<img class="tool-thumb" src="${esc(src)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}<div><strong>${esc(item.skin)}</strong><small>${esc(item.id)} · ${item.holesCount??item.slots.length}孔</small></div></div></td><td><div class="slots">${item.slots.map((v,i)=>`<span>${v}${item.unlocks?.[i]===0?' 🔒':''}</span>`).join('')||'无星格'}</div></td><td><strong>${money(item.priceCents)}</strong><small>☆ ${item.favorites}</small><small>${esc(freshness(item))} · ${esc(time(item.observedAt??state.latest?.at))}</small></td><td><button type="button" class="row-preview" data-search-preview="${n}">预览</button><button type="button" class="row-preview" data-search-compare="${n}">比较</button><button type="button" class="row-preview" data-search-verify="${n}">核验价格 / 状态</button></td></tr>`}).join('')||'<tr><td colspan="4" class="empty">暂无匹配样本，可调整范围或等待后续采集。</td></tr>';
 document.querySelectorAll('[data-search-verify]').forEach(button=>button.onclick=()=>verifyItem(result[(remoteCount===null?(page-1)*20:0)+Number(button.dataset.searchVerify)],button));
 $('#search-page').textContent=`${page} / ${pages}`;$('#search-prev').disabled=page<=1;$('#search-next').disabled=page>=pages;
 document.querySelectorAll('[data-search-preview]').forEach(button=>button.onclick=async()=>{try{preview(await fullItem(result[(remoteCount===null?(page-1)*20:0)+Number(button.dataset.searchPreview)]))}catch(e){$('#search-error').textContent=e.message}});document.querySelectorAll('[data-search-compare]').forEach(button=>button.onclick=async()=>{try{compare(await fullItem(result[(remoteCount===null?(page-1)*20:0)+Number(button.dataset.searchCompare)]));button.textContent='已加入'}catch(e){$('#search-error').textContent=e.message}});
}
function condition(){return {fields:Object.fromEntries(ids.map(id=>[id,$('#search-'+id).value])),ranges:Array.from({length:4},(_,i)=>({min:$('#search-min-'+i).value,max:$('#search-max-'+i).value,unlocked:$('#search-unlocked-'+i).checked}))}}
function restore(value){for(const id of ids)$('#search-'+id).value=value.fields?.[id]??'';$('#search-scope').value=value.fields?.scope||'inventory';$('#search-fresh').value=value.fields?.fresh||'all';$('#search-state').value=value.fields?.state||'all';for(let i=0;i<4;i++){const range=value.ranges?.[i];$('#search-min-'+i).value=range?.min??'';$('#search-max-'+i).value=range?.max??'';$('#search-unlocked-'+i).checked=range?.unlocked===true}apply()}
function drawSaved(){$('#search-presets').innerHTML=saved.map((preset,i)=>`<span><button type="button" data-saved-search="${i}">${esc(preset.name)}</button><button type="button" data-delete-search="${i}" aria-label="删除条件">×</button></span>`).join('');document.querySelectorAll('[data-saved-search]').forEach(b=>b.onclick=()=>restore(saved[Number(b.dataset.savedSearch)]));document.querySelectorAll('[data-delete-search]').forEach(b=>b.onclick=()=>{saved.splice(Number(b.dataset.deleteSearch),1);persist();drawSaved()})}
function persist(){try{localStorage.setItem('zx-search-presets',JSON.stringify(saved))}catch{$('#search-error').textContent='浏览器无法保存条件，本次会话仍可使用。'}}
$('#search-form').onsubmit=e=>{e.preventDefault();apply()};$('#search-sort').onchange=()=>apply();$('#search-scope').onchange=()=>apply();$('#search-fresh').onchange=()=>apply();$('#search-prev').onclick=()=>{page--;if(remoteCount===null)drawResults();else apply(false)};$('#search-next').onclick=()=>{page++;if(remoteCount===null)drawResults();else apply(false)};$('#search-reset').onclick=()=>{$('#search-form').reset();apply()};$('#search-save').onclick=()=>{try{filter();if(saved.length>=20)throw Error('最多保存20组条件');saved.push({name:$('#search-name').value.trim()||`${$('#search-skin').value||'全部谪星'} · ${$('#search-holes').value||'不限'}孔`,...condition()});persist();drawSaved()}catch(e){$('#search-error').textContent=e.message}};
$('#search-trend').onclick=()=>{try{window.dispatchEvent(new CustomEvent('trend-condition',{detail:filter()}));showTool('trends')}catch(e){$('#search-error').textContent=e.message}};
$('#search-export').onclick=()=>exportCSV('自定搜索结果.csv',[['商品ID','谪星','解锁孔数','星格','挂牌价_元','收藏','观察时间','商品链接'],...result.map(item=>[item.id,item.skin,item.holesCount??item.slots.length,item.slots.join('/'),item.priceCents/100,item.favorites,item.observedAt??state.latest?.at,item.url])]);

const gallery=createTool('gallery','图鉴','每一格，都有自己的样子。','官方谪星定义与本站真实商品样本，按星格数值查看外观。',`<section class="card"><div class="card-heading"><div><h2>本站行情样本（补充）</h2><p>官方定义＋真实观察样本，不推断未收录数值的外观。</p></div><span id="gallery-total" class="tag"></span></div><div class="tool-form"><div class="tool-grid"><label>搜索谪星<input id="gallery-query" placeholder="名称、英雄或武器"></label><label>品类<select id="gallery-category"><option value="">全部</option><option value="character">角色皮肤</option><option value="weapon">武器皮肤</option></select></label></div></div></section><div id="gallery-catalog" class="gallery-catalog"></div><section class="card" id="gallery-detail"><div class="card-heading"><div><h2 id="gallery-name">选择谪星查看详情</h2><p id="gallery-definition"></p></div><button id="gallery-to-sim" type="button" class="button secondary">样本洗练演练</button></div><div class="tool-form"><div class="tool-grid"><label>查看星格<select id="gallery-slot"></select></label><label>数值<select id="gallery-value"></select></label></div><p id="gallery-range" class="tool-message"></p></div><div id="gallery-samples" class="sample-grid"></div><div class="tool-pagination"><button id="gallery-more" class="button secondary">加载更多样本</button></div><p class="subtle-note">每张图对应整件真实商品，其他星格也会影响外观；这里不宣称是隔离其他条件后的单孔渲染。</p></section>`,'✦');
let gallerySkin='',sampleLimit=12;
function drawCatalog(){const query=$('#gallery-query').value.trim().toLowerCase(),category=$('#gallery-category').value;const catalog=state.catalog.filter(c=>(!category||c.category===category)&&(!query||(c.name+c.owner).toLowerCase().includes(query)));$('#gallery-total').textContent=`${state.catalog.length}种定义 · ${state.samples.length}组去重样本`;
 $('#gallery-catalog').innerHTML=catalog.map(c=>{const samples=state.samples.filter(i=>i.skin===c.name),current=state.pool.filter(i=>i.skin===c.name);return `<button type="button" class="card gallery-tile ${c.name===gallerySkin?'selected':''}" data-gallery="${esc(c.id)}"><strong>${esc(c.name)}</strong><span>${esc(c.owner)} · ${esc(c.quality)}</span><small>${c.category==='weapon'?'武器':'角色'} · ${c.slotNames?.length??0}星格 · ${samples.length}组样本</small><b>${current.length?money(Math.min(...current.map(i=>i.priceCents))):'暂无在售样本'}</b></button>`}).join('')||'<div class="card empty">暂无匹配定义。</div>';
 document.querySelectorAll('[data-gallery]').forEach(button=>button.onclick=()=>{gallerySkin=state.catalog.find(c=>c.id===button.dataset.gallery).name;sampleLimit=12;drawGalleryDetail(true);drawCatalog();$('#gallery-detail').scrollIntoView({behavior:'smooth',block:'start'})});
}
function drawGalleryDetail(reset=false){const entry=state.catalog.find(c=>c.name===gallerySkin);if(!entry)return;$('#gallery-name').textContent=entry.name;$('#gallery-definition').textContent=`${entry.owner} · ${entry.quality} · 官方星格：${entry.slotNames?.join(' / ')||'无星格'}`;
 const samples=state.samples.filter(i=>i.skin===gallerySkin),count=entry.slotNames?.length??samples[0]?.slots.length??0;
 if(reset){options($('#gallery-slot'),Array.from({length:count},(_,i)=>({value:String(i),label:entry.slotNames?.[i]??`第${i+1}格`})),'全部星格');$('#gallery-slot').value='';$('#gallery-value').value=''}
 const slot=$('#gallery-slot').value,values=slot===''?[]:[...new Set(samples.filter(i=>i.unlocks?.[Number(slot)]!==0).map(i=>i.slots[Number(slot)]).filter(Number.isSafeInteger))].sort((a,b)=>a-b);options($('#gallery-value'),values.map(v=>({value:String(v),label:String(v)})),'全部数值');
 const selected=$('#gallery-value').value,filtered=samples.filter(i=>slot===''||selected===''||(i.slots[Number(slot)]===Number(selected)&&i.unlocks?.[Number(slot)]!==0));
 $('#gallery-range').textContent=slot===''?`本站收录 ${samples.length} 组真实星格组合；样本不是全量图鉴。`:`该格已观察到 ${values.length} 个解锁数值${values.length?`，样本范围 ${values[0]}—${values.at(-1)}`:''}；不是官方全部合法范围。`;
 $('#gallery-samples').innerHTML=filtered.slice(0,sampleLimit).map((item,i)=>{const src=safeImageURL(item.thumbnail);return `<article class="sample-card"><div class="sample-image">${src?`<img src="${esc(src)}" alt="${esc(item.skin)}真实样本" loading="lazy" referrerpolicy="no-referrer">`:'<span>该历史样本暂无预览</span>'}</div><div><strong>${item.slots.join(' / ')||'无星格'}</strong><small>${item.holesCount??item.slots.length}孔 · 观察价 ${money(item.priceCents)}</small><small>${esc(time(item.observedAt))}</small><button class="row-preview" type="button" data-gallery-preview="${i}">查看样本</button><button class="row-preview" type="button" data-gallery-compare="${i}">比较</button></div></article>`}).join('')||'<div class="empty">该条件尚无真实样本。</div>';
 document.querySelectorAll('[data-gallery-preview]').forEach(b=>b.onclick=()=>preview(filtered[Number(b.dataset.galleryPreview)]));document.querySelectorAll('[data-gallery-compare]').forEach(b=>b.onclick=()=>{compare(filtered[Number(b.dataset.galleryCompare)]);b.textContent='已加入'});$('#gallery-more').disabled=sampleLimit>=filtered.length;
}
$('#gallery-query').oninput=drawCatalog;$('#gallery-category').onchange=drawCatalog;$('#gallery-slot').onchange=()=>{$('#gallery-value').value='';sampleLimit=12;drawGalleryDetail()};$('#gallery-value').onchange=()=>{sampleLimit=12;drawGalleryDetail()};$('#gallery-more').onclick=()=>{sampleLimit+=12;drawGalleryDetail()};$('#gallery-to-sim').onclick=()=>{window.dispatchEvent(new CustomEvent('simulate-skin',{detail:gallerySkin}));showTool('simulator')};
window.addEventListener('search-skin',event=>{$('#search-skin').value=event.detail;apply();showTool('search')});
onData(()=>{options($('#search-skin'),state.catalog,'全部谪星');apply(false);drawSaved();gallerySkin=gallerySkin||state.catalog[0]?.name||'';drawCatalog();drawGalleryDetail(!$('#gallery-slot').options.length)});activateInitial();
